data: {"index":1,"delta":{"text":" it the slowest of the three.\n\nJavaScript also utilizes automatic garbage collection, but its performance is significantly boosted by modern Just","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"-In-Time (JIT) compilation engines like Google’s V8. JIT engines compile JavaScript code into","type":"text"},"event_type":"step.delta"}

