data: {"index":1,"delta":{"text":" the raw execution speed of C and C++ while guaranteeing absolute memory safety, preventing common bugs like null pointer dereferences and","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" buffer overflows.\n\n### Concurrency and Execution Models\n\nConcurrency is handled differently by each language. Python historically relies on the","type":"text"},"event_type":"step.delta"}

