data: {"index":1,"delta":{"text":" operates on a single-threaded, non-blocking event loop. It handles highly concurrent tasks—such as thousands of simultaneous network requests—exceptionally","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" well using asynchronous callbacks, Promises, and `async/await` syntax. However, it is not naturally suited for heavy","type":"text"},"event_type":"step.delta"}

